/**
 * The topic-wise timetable for the test series.
 *
 * Transcribed from the schedule PDF -- eighty-four days from the first paper to
 * the exam, each naming its Professional Knowledge topic and the Quant,
 * Reasoning and English item that sits beside it. It is a plan, not state:
 * nothing here is read from or written to the database, and no paper in the
 * `tests` table is linked to a row of it. A student reads it to know what is
 * coming; an admin reads it to know what to set.
 *
 * Which is why it lives as a module rather than a table. The plan changes when
 * somebody decides it should, in a commit, with the change visible in a diff --
 * not through a screen nobody would open twice. If it ever needs editing in the
 * product, that is a migration and a repo away, and this shape is what it would
 * carry.
 *
 * The dates were checked against a 2026 calendar: day 1 is Monday 28 September
 * 2026 and each day is the one after the last, so `date` and `label` agree for
 * all eighty-four. `tests/schedule.test.ts` re-checks that on every run.
 */

/** One of the three non-PK subjects on a day, and the note the plan adds to it. */
export type ScheduleSubject = {
  item: string
  /** A theme or a qualifier -- "Theme: banking and economy". */
  note?: string
}

export type ScheduleDay = {
  /** 1..84, counting from the first paper. */
  day: number
  /** ISO, IST. The day this sits on. */
  date: string
  /** How the plan writes that date: "Mon 28 Sep". */
  label: string
  /** The syllabus slot, where there is one: "OS 1", "DBMS 3". */
  code?: string
  /** What the day is: a topic name, "Week 3 Test 1", "Review 2", "EXAM". */
  test: string
  /** "Pattern A · 55 Q · 45 min", or what stands in its place on a review day. */
  pattern?: string
  pk: {
    topic?: string
    /** Where it sits in its subject: "Operating Systems 1 of 4". */
    source?: string
    /** The sub-topics under the topic, in the plan's own smaller print. */
    detail?: string
    /**
     * What a day that is not one topic is made of: a weekly test's question
     * blueprint, a full mock's subject counts, what a review day is for.
     *
     * Kept in reading order rather than split by weight. The plan alternates a
     * bold count with a normal-weight subject -- "DBMS 5" "(Transactions)"
     * "CN 5" "(Transport)" -- and partitioning those by how they are set would
     * hand back two lists with no way to pair them up again.
     */
    plan?: string
  }
  /**
   * Absent on a day that has no separate QRE column -- a second weekly test, a
   * review day, the exam. The table spans the PK cell across the three.
   */
  quant?: ScheduleSubject
  reasoning?: ScheduleSubject
  english?: ScheduleSubject
}

export type ScheduleSection = {
  /** "Week 1", "Phase 2". */
  name: string
  /** The subjects it covers. Absent on a phase, which is not about subjects. */
  subjects?: string
  from: number
  to: number
  /** The span as the plan writes it: "28 Sep - 04 Oct". */
  dates: string
  days: ScheduleDay[]
}

