/** Every day, flat, in order. The sections are how it is read, not how it is stored. */
export const SCHEDULE_DAYS: ScheduleDay[] = SCHEDULE.flatMap((s) => s.days)

export const SCHEDULE_FIRST = SCHEDULE_DAYS[0]!.date
export const SCHEDULE_LAST = SCHEDULE_DAYS[SCHEDULE_DAYS.length - 1]!.date

/**
 * The day the plan puts on this date, or null if the date is outside it.
 *
 * Takes an IST date string because that is what every other date in this
 * application is; converting a clock to one is `istToday`'s job, not this.
 */
export function scheduleDayOn(date: string): ScheduleDay | null {
  return SCHEDULE_DAYS.find((d) => d.date === date) ?? null
}

/** The section a day belongs to. */
export function sectionOf(day: ScheduleDay): ScheduleSection {
  return SCHEDULE.find((s) => s.days.includes(day)) ?? SCHEDULE[0]!
}

/**
 * The next day on or after this date, for a date the plan has not reached yet.
 * Null once the plan is behind you.
 */
export function nextScheduleDay(date: string): ScheduleDay | null {
  return SCHEDULE_DAYS.find((d) => d.date >= date) ?? null
}

/**
 * How many days carry each pattern, which is the legend the PDF put on a cover
 * page this file does not have. Counted rather than written down, so it cannot
 * drift from the table underneath it.
 */
export function schedulePatterns(): { pattern: string; days: number }[] {
  const counts = new Map<string, number>()
  for (const d of SCHEDULE_DAYS) {
    if (!d.pattern?.startsWith('Pattern ')) continue
    counts.set(d.pattern, (counts.get(d.pattern) ?? 0) + 1)
  }
  return [...counts].sort().map(([pattern, days]) => ({ pattern, days }))
}
